/** Second exploration: learning-target-led graphic and smooth 3D illustration; no cutting. */
const fs = require('node:fs');
const path = require('node:path');
const { pathToFileURL } = require('node:url');
const { createRequire } = require('node:module');
const out = path.resolve(__dirname, '../output/worksheet-design-20261012/v2');
const runtimePackages = process.env.WORKSHEET_NODE_MODULES || path.join(require('node:os').homedir(), '.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules');
const { chromium } = createRequire(path.join(runtimePackages, '../package.json'))('playwright');
const motifs = { bag: [0,0], cat: [1,0], butterfly: [0,1], hat: [1,1], cup: [0,2], carrot: [1,2] };
const art = (style, motif, size) => {
  const [x,y] = motifs[motif];
  return `<span class="art" style="width:${size}px;height:${size}px"><img alt="${motif}" src="assets/${style}.png" style="left:${-100*x}%;top:${-100*y}%"></span>`;
};
const step = (n,title) => `<div class="step-title"><span>${n}</span><h2>${title}</h2></div>`;
const boxes = () => `<div class="boxes">${['가','가','가','','',''].map((t,i)=>`<div class="box ${i===0?'model':i<3?'trace':''}">${t}</div>`).join('')}</div>`;
const lines = (text) => `<div class="lines"><span>${text}</span></div>`;
const choice = (style,items) => `<div class="choices">${items.map(([m,t])=>`<div>${art(style,m,105)}<b>${t}</b><span class="answer-circle"></span></div>`).join('')}</div>`;
function sheet(style,lang,id){
  const ko = lang==='ko';
  return `<article id="sheet-${id}" class="page ${style} ${lang}"><header><img src="assets/logo.webp" alt="탱고북"><span>나의 첫 글자</span><b>${ko?'한글':'ENGLISH'}</b></header>
  <div class="heading"><p>${ko?'오늘의 글자':'TODAY’S LETTER'}</p><h1>${ko?'가를 배워요':'Let’s learn c'}</h1><div class="name">이름 <i></i> 날짜 <i></i></div></div>
  <div class="hero"><div class="letter-group"><div class="letter">${ko?'가':'C c'}</div><div class="blend">${ko?'ㄱ <em>+</em> ㅏ <em>=</em> 가':'c is for cat'}</div></div><div class="hero-picture">${art(style,ko?'bag':'cat',262)}<div class="word">${ko?'<strong>가</strong>방':'<strong>c</strong>at'}</div></div></div>
  <section>${step('1',ko?'‘가’를 따라 쓰고, 혼자 써요':'c를 따라 쓰고, 혼자 써요')}${ko?boxes():lines('c     c     c')+lines('')}</section>
  <section>${step('2',ko?'‘가’로 시작하는 그림에 동그라미 해요':'c로 시작하는 그림에 동그라미 해요')}${choice(style,ko?[['bag','가방'],['butterfly','나비'],['hat','모자']]:[['cat','cat'],['cup','cup'],['hat','hat']])}</section>
  <section class="finish">${step('3',ko?'빈칸에 ‘가’를 써서 낱말을 완성해요':'cat을 읽고 따라 써요')}${ko?`<div class="puzzle"><div class="box"></div><b>방</b><p>완성한 낱말을<br>소리 내어 읽어요.</p></div>`:`<div class="cat-blend"><b>c</b><span>a</span><span>t</span><i>→</i><strong>cat</strong></div>${lines('cat')}`}</section>
  <footer><span>TANGOBOOK · MY FIRST LETTERS</span><span>오늘 배운 글자 ${ko?'가':'c'} <i></i></span><b>${String(id).padStart(2,'0')}</b></footer></article>`;
}
const css = `
*{box-sizing:border-box}body{margin:0;background:#f2f1ed;font-family:'Malgun Gothic',Arial,sans-serif;color:#263341}h1,h2,p{margin:0}.page{--accent:#ef684e;--soft:#fff0e6;--line:#e6ded6;width:210mm;height:297mm;padding:12mm 14mm;background:white;position:relative;margin:22px auto;overflow:hidden;box-shadow:0 5px 35px #0001}.page.en{--accent:#277e75;--soft:#e5f4ee;--line:#d8e3dd}header{height:43px;display:flex;align-items:center;gap:20px}header img{width:93px;height:40px;object-fit:contain}header>span{font-size:12px;flex:1;letter-spacing:1px;color:#7c8490}header>b{font-size:10px;background:var(--soft);border-radius:14px;padding:7px 12px;color:var(--accent)}.heading{position:relative;border-top:1px solid var(--line);padding-top:22px;margin-top:7px}.heading>p{font-size:11px;font-weight:bold;letter-spacing:1.4px;color:var(--accent);margin-bottom:7px}.heading h1{font-size:33px;letter-spacing:-1px;font-weight:800;line-height:1.3}.name{position:absolute;right:0;bottom:2px;font-size:9px;display:flex;gap:7px;align-items:center;color:#8b8e93}.name i{display:inline-block;width:52px;height:11px;border-bottom:1px solid #ccd0d3}.hero{display:flex;height:310px;align-items:center;justify-content:space-around;border-bottom:1px solid var(--line);padding-bottom:10px}.letter-group{text-align:center;width:245px}.letter{font-size:145px;letter-spacing:-8px;font-weight:800;line-height:1.2;color:var(--accent)}.en .letter{font-family:Arial,sans-serif;font-size:115px;letter-spacing:-3px}.blend{display:flex;justify-content:center;gap:12px;font-size:25px;align-items:center;margin-top:15px}.blend em{font:17px Arial;color:#a0a2a7;font-style:normal}.en .blend{font:18px Arial;color:#747f87;letter-spacing:.4px}.hero-picture{display:flex;align-items:center;flex-direction:column}.art{display:inline-block;overflow:hidden;position:relative;flex-shrink:0;background:white}.art img{position:absolute;width:200%;height:300%;max-width:none;display:block}.word{font-size:33px;letter-spacing:0;font-weight:bold;line-height:1.15;margin-top:-21px;z-index:1}.word strong{color:var(--accent)}.en .word{font-family:Arial,sans-serif;font-size:34px}section{margin-top:26px}.step-title{display:flex;align-items:center;gap:10px;margin-bottom:14px}.step-title>span{font:700 12px Arial;display:grid;place-items:center;width:25px;height:25px;border-radius:8px;background:var(--soft);color:var(--accent)}h2{font-size:17px;font-weight:700;letter-spacing:-.6px;line-height:1.45}.boxes{display:flex;gap:11px}.box{height:86px;flex:1;border:1px solid var(--line);border-radius:12px;display:grid;place-items:center;font-size:47px;background:linear-gradient(to right,transparent calc(50% - .5px),#d7dadd50 50%,transparent calc(50% + .5px)),linear-gradient(to bottom,transparent calc(50% - .5px),#d7dadd50 50%,transparent calc(50% + .5px))}.box.model{color:var(--accent);background-color:var(--soft)}.box.trace{color:#b6bdc3}.choices{display:flex;justify-content:space-around}.choices>div{display:flex;flex-direction:column;align-items:center;width:170px}.choices b{font-size:18px;line-height:1.4;margin-top:4px}.en .choices b{font-family:Arial,sans-serif}.answer-circle{display:inline-block;border:1px solid #aeb8bc;width:19px;height:19px;border-radius:50%;margin-top:8px}.puzzle{display:flex;align-items:center;gap:15px;margin:6px 0 0 30px}.puzzle>.box{width:91px;height:86px;flex:0 0 91px}.puzzle>b{font-size:47px;font-weight:500}.puzzle p{font-size:12px;color:#808c91;line-height:1.7;margin-left:35px}.lines{height:59px;position:relative;border-bottom:1px solid #c7d7d2;background:linear-gradient(to bottom,transparent 12px,#d9e6df 12px,#d9e6df 13px,transparent 13px,transparent 29px,#b4ccc2 29px,#b4ccc2 30px,transparent 30px,transparent 47px,#d9e6df 47px,#d9e6df 48px,transparent 48px)}.lines span{position:absolute;left:13px;bottom:9px;font:45px/1 Arial;color:#b5bfbc;white-space:pre;letter-spacing:9px}.cat-blend{display:flex;gap:13px;font:26px Arial;align-items:center;height:37px;margin-bottom:7px}.cat-blend b{color:var(--accent)}.cat-blend i{font-size:17px;font-style:normal;color:#9fa8a9}.cat-blend strong{font-size:27px}footer{position:absolute;left:14mm;right:14mm;bottom:34px;border-top:1px solid var(--line);padding-top:13px;display:flex;align-items:center;gap:17px;font:9px Arial;color:#8a9298;letter-spacing:.8px}footer>span:nth-child(2){margin-left:auto;letter-spacing:0;font:11px 'Malgun Gothic',sans-serif;display:flex;align-items:center;gap:9px}footer i{width:18px;height:18px;border-radius:50%;border:1px solid var(--line)}footer b{font-size:13px;color:var(--accent)}.clay .heading h1{font-weight:600}.clay .step-title>span{border-radius:50%}.clay .box{border-radius:5px}.clay .letter{font-weight:600}.clay .hero{border-bottom:0;background:linear-gradient(90deg,#faf9fe 0,#faf9fe 49%,white 49%);border-radius:24px;margin-top:10px;height:300px}.clay .word{background:white;padding:5px 15px;border-radius:18px}.page.en section{margin-top:22px}.page.en .hero{height:284px}.page.clay.en .hero{height:274px}
.art{clip-path:inset(4%)}.word{margin-top:-3px}.hero-picture>.art{width:250px!important;height:250px!important}
@page{size:A4;margin:0}html{-webkit-print-color-adjust:exact;print-color-adjust:exact}@media print{body{background:white}.page{box-shadow:none;margin:0;break-after:page;page-break-after:always}.page:last-child{break-after:auto;page-break-after:auto}}
`;
const pages = ['graphic','clay'].flatMap((s,i)=>[sheet(s,'ko',i*2+1),sheet(s,'en',i*2+2)]);
const galleryCss = `.gallery{max-width:1120px;margin:auto;padding:35px 25px}.gallery>h1{font-size:29px}.gallery>p{font-size:13px;color:#717b85;line-height:1.8;margin-top:12px}.gallery>a{display:inline-block;font-size:12px;color:#3f675e;margin:18px 16px 0 0}.design{margin:30px 0 50px}.design>h2{font-size:21px;letter-spacing:-.5px}.design>p{font-size:12px;color:#6e7885;margin:8px 0 16px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:22px}.preview{position:relative;width:100%;aspect-ratio:210/297;overflow:hidden;background:white;box-shadow:0 5px 25px #18263315}.preview .page{position:absolute;left:0;top:0;margin:0;transform-origin:0 0;box-shadow:none}@media(max-width:700px){.pair{grid-template-columns:1fr}.gallery>h1{font-size:24px}}`;
const html = `<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>탱고북 학습지 2차 시안</title><style>${css}</style><body>${pages.join('')}</body></html>`;
const index = `<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>탱고북 · 학습지 2차 디자인</title><style>${css}${galleryCss}</style><body><div class="gallery"><h1>배우는 글자가 디자인의 중심</h1><p>가 → 가방, c → cat. 제목부터 그림과 활동까지 같은 학습 대상에 연결했습니다.<br>읽기 · 그림 찾기 · 쓰기로 구성했습니다.</p><a href="TangoBook-Worksheets-v2.pdf" target="_blank">A4 4장 PDF</a><a href="sheets.html" target="_blank">실제 크기로 보기</a>${[['또렷한 그래픽','질감 없는 둥근 도형과 선명한 색. 가볍고 현대적인 교재 느낌입니다.'],['부드러운 입체','매끈한 입체 사물과 단순한 형태. 캐릭터와 교구에 가까운 느낌입니다.']].map((t,i)=>`<div class="design"><h2>${i+1}. ${t[0]}</h2><p>${t[1]}</p><div class="pair">${pages.slice(i*2,i*2+2).map(p=>`<div class="preview">${p}</div>`).join('')}</div></div>`).join('')}</div><script>function fit(){document.querySelectorAll('.preview').forEach(w=>w.firstElementChild.style.transform='scale('+w.clientWidth/w.firstElementChild.offsetWidth+')')}addEventListener('resize',fit);document.fonts.ready.then(fit);fit();</script></body></html>`;
async function main(){
  fs.mkdirSync(path.join(out,'previews'),{recursive:true});
  fs.writeFileSync(path.join(out,'sheets.html'),html);fs.writeFileSync(path.join(out,'index.html'),index);
  const executablePath=[chromium.executablePath(),'C:/Program Files/Google/Chrome/Application/chrome.exe','C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'].find(p=>fs.existsSync(p));
  const browser=await chromium.launch({headless:true,executablePath});
  try{
    const tab=await browser.newPage({viewport:{width:1250,height:1700}});
    await tab.goto(pathToFileURL(path.join(out,'sheets.html')).href);await tab.evaluate(async()=>{await document.fonts.ready;await Promise.all(Array.from(document.images).map(i=>i.decode()))});
    const checks=await tab.evaluate(()=>Array.from(document.querySelectorAll('.page')).map(p=>({id:p.id,missingImages:Array.from(p.querySelectorAll('img')).filter(i=>!i.naturalWidth).length,bottom:p.querySelector('.finish').getBoundingClientRect().bottom-p.getBoundingClientRect().top,footer:p.querySelector('footer').getBoundingClientRect().top-p.getBoundingClientRect().top})));
    if(checks.some(x=>x.missingImages||x.bottom>x.footer-10))throw new Error(JSON.stringify(checks));
    if(/오리|붙이|토끼|텃밭|garden/.test(html))throw new Error('Excluded activity or unrelated theme present');
    await tab.pdf({path:path.join(out,'TangoBook-Worksheets-v2.pdf'),printBackground:true,preferCSSPageSize:true});
    for(let i=1;i<=4;i++)await tab.locator(`#sheet-${i}`).screenshot({path:path.join(out,`previews/sheet-${i}.png`)});
    await tab.goto(pathToFileURL(path.join(out,'index.html')).href);await tab.evaluate(async()=>{await document.fonts.ready;await Promise.all(Array.from(document.images).map(i=>i.decode()))});
    for(let i=0;i<2;i++)await tab.locator('.design').nth(i).screenshot({path:path.join(out,`previews/design-${i+1}.png`)});
    await tab.setViewportSize({width:390,height:844});const overflow=await tab.evaluate(()=>document.documentElement.scrollWidth>innerWidth);if(overflow)throw new Error('Mobile overflow');
    fs.writeFileSync(path.join(out,'layout-checks.json'),JSON.stringify({checks,mobileOverflow:overflow},null,2));console.log(JSON.stringify(checks));
  }finally{await browser.close()}
}
main().catch(e=>{console.error(e);process.exitCode=1});
